    const a = project(cam, runway.cx, y + 0.1, z);
    const b = project(cam, runway.cx, y + 0.1, Math.min(z + 22, runway.z1 - 6));
    if (a && b) { ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke(); }
